                moveType = Ug.MoveType.Ground;

            TargetType = -1;
            if (moveType == Ug.MoveType.Ground)
                TargetType = 0;
            else if (moveType == Ug.MoveType.Water)
                TargetType = 1;

            posList = PositionDatas.FindAll(x => x.Key == TargetType);
            if (posList.Count != 0)
